    def xǁProbeHelperǁhandle_nozzle_move__mutmut_orig(self, direction: str) -> None:
        """Handle move z buttons click"""
        if direction == "raise":
            _gcode = f"TESTZ Z={self._zhop_height}"
        elif direction == "lower":
            _gcode = f"TESTZ Z=-{self._zhop_height}"
        else:
            return

        self.accept_button.show()
